}
function drawShrine(s){let x=s.x-cam;R(x-11,204,22,28,'#35282b');R(x-8,199,16,5,'#846648');R(x-6,202,12,2,'#c29a61');R(x-3,208,6,14,'#110e13');R(x-1,211,2,8,s.active?'#f3c878':'#6a362d');if(s.active){ctx.globalAlpha=.2;ctx.fillStyle='#efb66d';ctx.beginPath();ctx.arc(x,215,20,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}R(x-3,193,6,2,'#b19165')}
