function drawPlayer(){let x=Math.round(player.x-cam),y=Math.round(player.y);if(player.inv>0&&Math.floor(performance.now()/70)%2===0)return;
// shadow
R(x-3,y+player.h,19,3,'#171116');if(player.attack>0){R(x+(player.face>0?10:-12),y+9,13,3,'#d8c8a9');R(x+(player.face>0?20:-14),y+7,4,3,'#fff0ce')}
